using Mbb.Archive.Modules.Retention.Application.Queries;
using Mbb.Archive.Modules.Retention.Application;
using Microsoft.EntityFrameworkCore;using Microsoft.Extensions.Configuration;using Microsoft.Extensions.DependencyInjection;using Mbb.Archive.BuildingBlocks.Application;using Mbb.Archive.Modules.Retention.Application.Abstractions;using Mbb.Archive.Modules.Retention.Application.Cases.Schedule;using Mbb.Archive.Modules.Retention.Application.Holds.Place;using Mbb.Archive.Modules.Retention.Application.Holds.Release;using Mbb.Archive.Modules.Retention.Application.Rules.Create;using Mbb.Archive.Modules.Retention.Infrastructure.Messaging;using Mbb.Archive.Modules.Retention.Infrastructure.Persistence;
namespace Mbb.Archive.Modules.Retention.Infrastructure;public static class RetentionModule{public static IServiceCollection AddRetentionModule(this IServiceCollection s,IConfiguration c){var cs=c.GetConnectionString("Retention");if(string.IsNullOrWhiteSpace(cs))throw new InvalidOperationException("Connection string 'Retention' is not configured.");s.AddDbContext<RetentionDbContext>(o=>o.UseNpgsql(cs));s.AddSingleton(TimeProvider.System);s.AddScoped<IRetentionRepository,EfRetentionRepository>();s.AddScoped<IUnitOfWork<RetentionBoundary>>(sp=>sp.GetRequiredService<RetentionDbContext>());s.AddScoped<IInbox<RetentionBoundary>>(sp=>sp.GetRequiredService<RetentionDbContext>());s.AddScoped<IOutbox<RetentionBoundary>>(sp=>sp.GetRequiredService<RetentionDbContext>());s.AddScoped<IRetentionQueries,EfRetentionQueries>().AddScoped<RetentionQueryHandlers>().AddScoped<CreateRetentionRuleCommandHandler>();s.AddScoped<ScheduleRetentionCaseCommandHandler>();s.AddScoped<PlaceLegalHoldCommandHandler>();s.AddScoped<ReleaseLegalHoldCommandHandler>();s.AddHostedService<ArchiveDeclaredRetentionConsumer>();s.AddHostedService<RetentionEvaluator>();s.AddHostedService<RetentionOutboxPublisher>();return s;}}
